#!/usr/bin/env node
// Generates src/data/lists.ts from the versioned text lists in src/data/.
//
// The .txt files are the source of truth so they can be reviewed and updated
// without touching code. Run `npm run build:data` after editing them; CI fails
// if the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const dataDir = join(here, '..', 'src', 'data');
const outFile = join(dataDir, 'lists.ts');

function readList(name, { numeric = false } = {}) {
  const raw = readFileSync(join(dataDir, name), 'utf8');
  const values = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    values.push(numeric ? Number(trimmed) : trimmed);
  }
  return values;
}

const bots = readList('bots.txt');
const asns = readList('datacenter_asns.txt', { numeric: true });

const banner = '// Generated by scripts/build-data.mjs from src/data/*.txt. Do not edit by hand.\n';

const body = `${banner}
/** Lowercase User-Agent substrings for known bots (design/worker.md §7). */
export const BOT_PATTERNS: string[] = ${JSON.stringify(bots, null, 2)};

/** Hosting / cloud ASNs treated as datacenter traffic at strict level. */
export const DATACENTER_ASNS: number[] = ${JSON.stringify(asns)};
`;

writeFileSync(outFile, body);
console.log(`Wrote ${outFile} (${bots.length} bot patterns, ${asns.length} ASNs)`);
